input.command:
python3 -c "
import re, json
with open('/tmp/tracker_issue_3772.html') as f:
    text = f.read()
matches = re.findall(r'<script type=\"application/json\" data-target=\"react-app.embeddedData\">(.*?)</script>', text, re.DOTALL)
for m in matches:
    try:
        data = json.loads(m)
        if 'payload' in data and 'preloadedQueries' in data['payload']:
            for q in data['payload']['preloadedQueries']:
                if 'result' in q and 'data' in q['result']:
                    issue = q['result']['data'].get('repository', {}).get('issue', {})
                    if issue:
                        print('Issue #', issue.get('number'))
                        print('UpdatedAt:', issue.get('updatedAt'))
                        print('CreatedAt:', issue.get('createdAt'))
                        # Check timeline items for comments
                        front = issue.get('frontTimelineItems', {})
                        print('Front timeline total:', front.get('totalCount'))
                        for edge in front.get('edges', []):
                            node = edge.get('node', {})
                            print('Timeline item:', node.get('__typename'))
                            if node.get('__typename') == 'IssueComment':
                                print('  Comment author:', node.get('author', {}).get('login'))
                                print('  Comment created:', node.get('createdAt'))
                        back = issue.get('backTimelineItems', {})
                        print('Back timeline total:', back.get('totalCount'))
    except Exception as e:
        pass
"

